/* V23: browser-local continuation, completed shows, and deterministic scene details. */
const PLAY_KEYS={current:'island-v23-current',history:'island-v23-history',endings:'island-v3-endings',events:'island-v5-events'};
let savedVoyage=null,playHistory=[],historyReadOnly=false,saveProblem='',saveSignature='',historySignature='',resetMessage='';
const plainObject=x=>x&&typeof x==='object'&&!Array.isArray(x)&&Object.getPrototypeOf(x)===Object.prototype;
function validRun(raw){try{
 if(!plainObject(raw)||raw.version!==17||!['prep','live','incident','farewell','encore','result'].includes(raw.phase))return null;
 const integer=(v,a,b)=>Number.isSafeInteger(v)&&v>=a&&v<=b,txt=(v,n)=>typeof v==='string'&&Array.from(v).length<=n,arr=(v,n)=>Array.isArray(v)&&v.length<=n;
 if(!integer(raw.seed,0,1e12)||!integer(raw.step,0,FLOW.length-1)||!txt(raw.name,16)||!raw.name)return null;
 const bounds={audience:[0,100],budget:[0,110],time:[0,125],cohesion:[0,100],cursor:[0,100],encores:[0,60],rest:[0,2],elapsed:[0,84],limit:[84,84],specialPractice:[0,300],practiceCount:[0,100],techProgress:[0,300],misses:[0,100],corrections:[0,2],encorePage:[0,100]};
 for(const [k,[a,b]]of Object.entries(bounds))if(!integer(raw[k],a,b))return null;
 for(const k of ['sat','energy','ready','lastCost','streak'])if(!Array.isArray(raw[k])||raw[k].length!==4||!raw[k].every(v=>integer(v,0,100)))return null;
 if(!arr(raw.set,30)||!raw.set.length||raw.set[0]!=='new-again'||new Set(raw.set).size!==raw.set.length||raw.set.some(id=>!track(id)))return null;
 if(!arr(raw.news,2)||new Set(raw.news).size!==raw.news.length||raw.news.some(id=>!OPTIONAL_NEW_TRACKS.some(x=>x.id===id)))return null;
 if(!SPECIALS.some(x=>x.id===raw.special)||raw.bridge!=null&&!FAN_BRIDGES.some(x=>x.id===raw.bridge))return null;
 const itemOK=it=>plainObject(it)&&((it.kind==='track'&&!!track(it.id))||(it.kind==='special'&&SPECIALS.some(x=>x.id===it.id&&x.id!=='none'))||(it.kind==='bridge'&&FAN_BRIDGES.some(x=>x.id===it.id))||(it.kind==='challenge'&&it.id==='challenge-stage'))&&(it.short===undefined||typeof it.short==='boolean')&&(it.quality===undefined||integer(it.quality,0,100));
 if(!arr(raw.queue,100)||!raw.queue.every(itemOK)||!arr(raw.performed,100)||!raw.performed.every(itemOK)||raw.cursor>raw.queue.length)return null;
 if(raw.phase==='live'&&(!raw.queue.length||raw.cursor>=raw.queue.length))return null;
 if(!arr(raw.hiddenSeen,3)||raw.hiddenSeen.some(k=>!Object.hasOwn(HIDDEN_EVENTS,k))||!plainObject(raw.hiddenDecisions)||Object.entries(raw.hiddenDecisions).some(([k,v])=>!Object.hasOwn(HIDDEN_EVENTS,k)||![0,1].includes(v)))return null;
 if(!arr(raw.incidentSeen,12)||raw.incidentSeen.some(k=>!Object.hasOwn(LIVE_INCIDENTS,k))||raw.incident!==null&&!Object.hasOwn(LIVE_INCIDENTS,raw.incident)||raw.phase==='incident'&&!raw.incident)return null;
 if(!plainObject(raw.picks))return null;
 for(const [k,v]of Object.entries(raw.picks)){if(Object.hasOwn(DECISIONS,k)){if(!DECISIONS[k].options.some(o=>o[2]===v)&&v!=='basic')return null}else if(k==='personal'){if(!plainObject(v)||Object.entries(v).some(([who,id])=>!['0','1','2','3'].includes(who)||!PERSONAL_TRACKS().some(t=>t.id===id&&t.soloMember===Number(who))))return null}else if(k==='pace'){if(typeof v!=='boolean')return null}else{const choices={domino:['solo','band'],release:['new','hold'],memory:['rework','hint','new'],cute:['props','talk','simple'],fan:['listen','small','hold']};if(!choices[k]?.includes(v))return null}}
 if(raw.challenge!==null&&(!plainObject(raw.challenge)||!Array.isArray(raw.challenge.ids)||raw.challenge.ids.length!==4||raw.challenge.ids.some(id=>!CHALLENGES.some(x=>x.id===id))||!integer(raw.challenge.practice,0,200)||!integer(raw.challenge.opt,0,3)))return null;
 if(!arr(raw.challengeResult,4)||raw.challengeResult.some(r=>!plainObject(r)||!integer(r.member,0,3)||!CHALLENGES.some(x=>x.id===r.id)||!['perfect','close','recover','miss'].includes(r.result)||!integer(r.rating,-1000,1000)))return null;
 for(const k of ['log','fixed','unresolved'])if(!arr(raw[k],300)||raw[k].some(x=>!txt(x,k==='log'?1000:100)))return null;
 if(!txt(raw.feedback,1000))return null;
 for(const k of ['acknowledged','audienceUsed'])if(typeof raw[k]!=='boolean')return null;
 for(const k of ['restAtCurrent','fatigueResolved','fatigueReturn'])if(raw[k]!==undefined&&typeof raw[k]!=='boolean')return null;
 if(raw.callCount!==undefined&&!integer(raw.callCount,0,3)||raw.choirSong!==undefined&&!FAN_CHOIR_SONGS.includes(raw.choirSong))return null;
 if(raw.phase==='result'?!Object.hasOwn(Game.ENDINGS,raw.final):raw.final!==null)return null;
 if(!Array.isArray(raw.hints)||raw.hints.length!==4||raw.hints.some((h,i)=>h!==null&&(!plainObject(h)||h.who!==i||!integer(h.step,0,FLOW.length-1)||!txt(h.title,150)||!txt(h.reason,1000)||!txt(h.action,150))))return null;
 if(raw.concertName!==undefined&&!txt(raw.concertName,24)||raw.journalId!==undefined&&(!txt(raw.journalId,80)||!/^[a-z0-9-]+$/i.test(raw.journalId)))return null;
 if(raw.draftChallenge!==undefined&&(!Array.isArray(raw.draftChallenge)||raw.draftChallenge.length!==4||raw.draftChallenge.some(id=>!CHALLENGES.some(x=>x.id===id))))return null;
 if(raw.draftRelease!==undefined&&(!arr(raw.draftRelease,3)||raw.draftRelease.some(id=>!OPTIONAL_NEW_TRACKS.some(x=>x.id===id))))return null;
 if(raw.cues!==undefined&&(!arr(raw.cues,2)||raw.cues.some(q=>!plainObject(q)||!['talk','band','signal'].includes(q.key)||!integer(q.cursor,0,99))||new Set(raw.cues.map(q=>q.cursor)).size!==raw.cues.length))return null;
 if(raw.meetingNotes!==undefined&&(!plainObject(raw.meetingNotes)||Object.entries(raw.meetingNotes).some(([k,v])=>!['0','1','2','3'].includes(k)||![0,1,2].includes(v))))return null;
 if(raw.meetingRecalled!==undefined&&(!arr(raw.meetingRecalled,4)||new Set(raw.meetingRecalled).size!==raw.meetingRecalled.length||raw.meetingRecalled.some(i=>!integer(i,0,3))))return null;
 const out=Game.fresh(raw.name,raw.seed),extras=['bridge','callCount','choirSong','restAtCurrent','fatigueResolved','fatigueReturn','concertName','journalId','draftChallenge','draftRelease','cues','meetingNotes','meetingRecalled'];for(const k of [...Object.keys(out),...extras])if(Object.hasOwn(raw,k))out[k]=JSON.parse(JSON.stringify(raw[k]));return out;
 }catch{return null}}
function loadPlayRecords(){try{const text=localStorage.getItem(PLAY_KEYS.current);if(text){const record=JSON.parse(text),state=record?.schema===1?validRun(record.state):null;if(state&&Number.isFinite(record.savedAt))savedVoyage={schema:1,savedAt:record.savedAt,state};else saveProblem='지난 저장을 읽지 못했어. 새 공연을 시작하거나 전체 초기화로 정리할 수 있어.'}const records=JSON.parse(localStorage.getItem(PLAY_KEYS.history)||'[]');if(Array.isArray(records))playHistory=records.slice(0,20).map(r=>{const state=r?.schema===1?validRun(r.state):null;return state?.phase==='result'&&Number.isFinite(r.savedAt)?{schema:1,savedAt:r.savedAt,state}:null}).filter(Boolean)}catch{saveProblem='이 브라우저에서 저장 기록을 불러오지 못했어. 지금 공연은 계속 준비할 수 있어.'}}
loadPlayRecords();
function runIdentity(s){return s.journalId||(s.journalId=s.seed.toString(36)+'-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,8))}
function persistVoyage(){if(!S||historyReadOnly)return;runIdentity(S);const state=validRun(S);if(!state){saveProblem='현재 공연을 저장하지 못했어. 페이지를 닫기 전에 공연 일지를 챙겨줘.';return}const signature=JSON.stringify(state);if(signature===saveSignature)return;const record={schema:1,savedAt:Date.now(),state};let currentOK=false;try{localStorage.setItem(PLAY_KEYS.current,JSON.stringify(record));savedVoyage=record;saveSignature=signature;saveProblem='';currentOK=true}catch{saveProblem='자동 저장을 할 수 없어. 브라우저 저장 공간을 확인하고, 페이지를 닫기 전에 티켓이나 공연 일지를 챙겨줘.'}
 if(state.phase==='result'&&signature!==historySignature){const next=[record,...playHistory.filter(r=>r.state.journalId!==state.journalId)].slice(0,20);try{localStorage.setItem(PLAY_KEYS.history,JSON.stringify(next));playHistory=next;historySignature=signature}catch{saveProblem=currentOK?'이 공연은 저장됐지만 지난 공연 목록에 추가하지 못했어. 티켓이나 공연 일지를 챙겨줘.':saveProblem}}}
function savedDate(n){try{return new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',month:'long',day:'numeric',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(n))}catch{return ''}}
function savedStop(s){return s.phase==='result'?Game.ENDINGS[s.final][0]:s.phase==='prep'?STOPS[Game.step(s).stop].name:s.phase==='incident'?'무대의 돌발 상황':s.phase==='live'?'본공연 '+(s.cursor+1)+'번째 무대':s.phase==='farewell'?'마지막 인사':'앵코르 대기'}
function savedVoyageCard(){return `<section class="continue-area">${resetMessage?`<p class="reset-message" role="status">${esc(resetMessage)}</p>`:''}${savedVoyage?`<div class="continue-card"><div><span class="eyebrow">A VOYAGE WAITING FOR YOU</span><h3>${esc(concertTitle(savedVoyage.state))}</h3><p>${esc(savedStop(savedVoyage.state))} · ${savedDate(savedVoyage.savedAt)} 저장</p></div><button class="primary" onclick="resumeVoyage()">${savedVoyage.state.phase==='result'?'지난 공연 결과 보기':'지난 공연 준비 이어가기'} ↗</button></div>`:''}${saveProblem?`<p class="save-warning" role="status">${esc(saveProblem)}</p>`:''}</section>`}
const landingBeforeVoyage=landing;landing=function(){const html=landingBeforeVoyage();return savedVoyage?savedVoyageCard()+html:html+savedVoyageCard()};
function resumeVoyage(){if(!savedVoyage)return;const state=validRun(savedVoyage.state);if(!state){saveProblem='저장된 공연을 열지 못했어.';render();return}S=state;historyReadOnly=false;lastChoiceEcho=null;resetMessage='';closeModal();render();topPage()}
function startFreshVoyage(){const name=$('#player')?.value?.trim()||'왈왈이';S=Game.fresh(name);runIdentity(S);historyReadOnly=false;lastChoiceEcho=null;resetMessage='';closeModal();render();topPage()}
start=function(){if(savedVoyage&&savedVoyage.state.phase!=='result'){modal(`<span class="eyebrow">ONE VOYAGE AT A TIME</span><h2>준비하던 공연이 남아 있어.</h2><p>이어가거나, 새 공연으로 바꿔 시작할 수 있어. 새로 시작하면 진행 중인 저장은 새 공연으로 바뀐다.</p><div class="record-modal-actions"><button class="primary" onclick="resumeVoyage()">준비하던 공연 이어가기 ↗</button><button class="secondary" onclick="startFreshVoyage()">새 공연으로 시작</button></div>`);return}startFreshVoyage()};
home=function(){if(S&&!historyReadOnly)persistVoyage();S=null;historyReadOnly=false;lastChoiceEcho=null;render();topPage()};
function openPlayHistory(){modal(`<section class="play-record-book"><span class="eyebrow">THE CONCERTS WE MADE</span><h2>우리의 지난 공연들.</h2><p>최근 ${playHistory.length}개의 공연 · 최대 20개까지 이 브라우저에 남는다.</p><div class="play-record-list">${playHistory.map((r,i)=>{const s=r.state;return `<button onclick="readPlayRecord(${i})"><span class="record-number">${String(playHistory.length-i).padStart(2,'0')}</span><div><small>${savedDate(r.savedAt)}</small><h3>${esc(concertTitle(s))}</h3><p>${esc(Game.ENDINGS[s.final][0])}</p><span>${s.performed.length}개 무대 · 앵콜 ${s.encores}곡 · 관객 ${Math.round(s.audience)}</span></div><b>↗</b></button>`}).join('')||'<div class="empty-record"><span>✧</span><p>아직 완성한 공연이 없어.<br>첫 공연의 마지막 장면부터 한 장씩 남겨보자.</p></div>'}</div><p class="fine">기록을 열면 셋리스트와 티켓을 다시 볼 수 있어. 준비 중인 공연은 그대로 남아 있다.</p><button class="textbtn" onclick="confirmPlayReset()">플레이 기록 전체 초기화 ↗</button></section>`)}
function readPlayRecord(i){if(!Number.isInteger(i)||!playHistory[i])return;const state=validRun(playHistory[i].state);if(!state)return;if(S&&!historyReadOnly&&S.phase!=='result')persistVoyage();S=state;historyReadOnly=true;lastChoiceEcho=null;closeModal();render();topPage()}
function confirmPlayReset(){modal(`<span class="eyebrow">A CLEAN PAGE</span><h2>플레이 기록을 모두 지울까?</h2><p>진행 중인 저장, 지난 공연 ${playHistory.length}개, 모은 엔딩 ${collection.length}개와 숨은 항해 ${foundEvents.length}개를 함께 비운다.</p><form onsubmit="resetPlayRecords(event)"><label for="reset-play-confirm">아래에 <b>초기화</b>를 입력해 주세요.</label><input id="reset-play-confirm" class="concert-title-input" autocomplete="off" maxlength="3" required><p id="reset-play-message" role="status"></p><div class="record-modal-actions"><button class="secondary" type="button" onclick="closeModal()">기록 남겨두기</button><button class="primary reset-confirm" type="submit">모든 플레이 기록 지우기</button></div></form>`)}
function resetPlayRecords(event){event.preventDefault();if($('#reset-play-confirm').value.trim()!=='초기화'){$('#reset-play-message').textContent='초기화를 입력하면 기록을 비울 수 있어.';return}try{for(const key of Object.values(PLAY_KEYS))localStorage.removeItem(key);if(Object.values(PLAY_KEYS).some(key=>localStorage.getItem(key)!==null))throw Error('retained')}catch{$('#reset-play-message').textContent='기록을 지우지 못했어. 브라우저 저장 설정을 확인해 주세요.';return}S=null;savedVoyage=null;playHistory=[];collection=[];foundEvents=[];historyReadOnly=false;lastChoiceEcho=null;saveSignature='';historySignature='';saveProblem='';resetMessage='모든 플레이 기록을 비웠어. 새 항해를 시작해보자.';closeModal();render();topPage()}
function recordHeader(){const root=document.querySelector('.headlinks');if(root&&!root.querySelector('.play-history-button'))root.insertAdjacentHTML('beforeend','<button class="play-history-button" onclick="openPlayHistory()">기록</button><button class="play-reset-button" onclick="confirmPlayReset()">초기화</button>')}
const renderBeforeVoyage=render;render=function(){if(!S)historyReadOnly=false;persistVoyage();renderBeforeVoyage();recordHeader();if(S){const root=document.querySelector('.workspace')||document.querySelector('.result');if(root){const msg=historyReadOnly?'지난 공연을 다시 읽는 중 · 현재 준비는 그대로 남아 있어':saveProblem||'이 브라우저에 자동 저장됨';root.insertAdjacentHTML('afterbegin',`<div class="autosave-note ${saveProblem?'save-warning':''}" role="status">${esc(msg)}</div>`)}}};
const askBeforeVoyage=askMemberHint;askMemberHint=function(who){askBeforeVoyage(who);persistVoyage()};
const challengePreviewBeforeVoyage=updateChallengePreview;updateChallengePreview=function(who){challengePreviewBeforeVoyage(who);if(S&&Game.step(S)?.type==='challenge'){S.draftChallenge=MEMBERS.map((m,i)=>$('#challenge-'+i).value);persistVoyage()}};
function saveReleaseDraft(){if(!S)return;S.draftRelease=[...document.querySelectorAll('input[name="newtracks"]:checked')].map(el=>el.value);persistVoyage()}
const releaseBeforeVoyage=releaseView;releaseView=function(){return releaseBeforeVoyage().replace(/<input type="checkbox" name="newtracks" value="([^"]+)">/g,(html,id)=>html.slice(0,-1)+` onchange="saveReleaseDraft()" ${S.draftRelease?.includes(id)?'checked':''}>`)};
/* Rendering variants never use or advance the gameplay random stream. */
function storyVariant(s,key,count=2){let n=(s?.seed||0)>>>0;for(const c of key)n=Math.imul(n^c.charCodeAt(0),16777619)>>>0;n^=n>>>16;n=Math.imul(n,2246822507);n^=n>>>13;return (n>>>0)%count}
const CHALLENGE_OTHER_LINES={
 cute:{ready:['하트 모양을 손으로 맞춰보다가, 너무 큰가 싶어 작게 다시 만들어본다.','입으로는 어렵다면서도 손끝은 벌써 포인트 동작을 따라간다.','마지막 포즈를 거울처럼 따라 해보다가 혼자 웃음을 터뜨린다.','멤버들에게 한 번만 봐달라더니, 막상 시선이 모이자 웃으며 고개를 돌린다.'],success:['작은 애교 포즈를 남긴 뒤 쑥스러운 듯 웃는다. 그 표정에 객석의 환호가 한 번 더 터진다.','손하트를 끝까지 지키다가 노래가 멎자마자 두 손을 내린다. 웃음은 조금 더 남는다.','볼 옆에 손을 올린 채 잠깐 버티더니, 부끄러운지 눈을 꼭 감고 웃는다.','마지막 애교를 또박또박 보여주고는 멤버들 뒤로 한 걸음 물러선다. 함성에 다시 웃는다.'],stumble:['애교 포즈를 반대로 해버리고는 자기 손을 보며 웃는다. 마지막에는 작은 하트로 인사한다.','어떤 손부터 올릴지 잠깐 헷갈린다. 어색한 브이가 귀여웠다는 듯 객석에서 함성이 난다.','하트를 만들던 손을 어디에 둘지 잊고 그대로 웃어버린다. 옆 멤버가 포즈를 같이 잡는다.','자신 있게 시작한 애교가 웃음으로 끝난다. 놓친 동작 대신 객석에 두 번 손을 흔든다.']},
 sexy:{ready:['진지한 표정을 한번 지어보다가 옆 멤버의 시선을 못 이기고 웃는다.','카메라와 눈을 맞출 자리를 확인한다. 잠깐 웃음을 참고 다시 고개를 든다.','포인트 동작을 아주 작게 연습한다. 자기 차례가 되자 괜히 소매를 한번 만진다.','시선만큼은 자신 있다는 듯 고개를 들었다가, 멤버의 장난에 바로 웃음을 터뜨린다.'],success:['시선을 끝까지 지킨 뒤 음악이 멎자 먼저 웃어버린다. 앞줄의 함성이 한 박자 늦게 커진다.','포인트 동작 뒤로 짧은 눈맞춤을 남긴다. 멤버들이 환호하자 쑥스럽게 어깨를 움츠린다.','끝 포즈까지 진지하게 버티더니, 바로 눈을 피하며 웃는다. 객석이 그 틈을 놓치지 않는다.','마지막 동작에서 카메라를 한번 바라본다. 멤버의 박수를 듣자 금세 수줍은 얼굴이 된다.'],stumble:['포인트 동작보다 웃음이 먼저 나와버린다. 멤버 쪽을 한번 보고 끝 포즈만 다시 잡는다.','눈빛을 준비하다가 발동작을 놓친다. 웃으며 고개를 저은 뒤 카메라에 짧게 인사한다.','마지막 시선을 어디에 둘지 헷갈려 객석과 눈이 마주친다. 부끄러운 듯 웃으며 한 발 물러선다.','힘을 주려던 순간 웃음이 터져 타이밍을 놓친다. 멤버의 손짓에 맞춰 마지막 포즈를 이어간다.']},
 power:{ready:['동작을 크게 펼쳐보다가 공간을 한번 확인한다. 옆 멤버에게 웃으며 한 걸음 비켜준다.','발 디딜 박자를 작게 세어본다. 어깨를 풀고 나니 표정부터 조금 자신 있어진다.','손과 발을 따로 연습하다가 이번에는 같이 움직여본다. 한 번 맞자 작게 고개를 끄덕인다.','박자를 두드리던 손이 어느새 춤으로 이어진다. 먼저 나가려다 자기 차례를 확인하고 웃는다.'],success:['큰 동작을 딱 멈춘 뒤 객석을 향해 환하게 웃는다. 멤버들이 박자를 두드리며 응답한다.','마지막 박자까지 힘 있게 닿고는 가볍게 숨을 고른다. 옆 멤버가 손바닥을 내민다.','어려운 동작을 넘기자 표정이 풀린다. 마지막 포즈에는 웃음까지 함께 얹는다.','끝난 줄 알면서도 리듬을 한 번 더 탄다. 멤버의 손짓을 보고 웃으며 자리를 넘긴다.'],stumble:['팔 동작을 크게 넣었다가 한 박자 빨라진다. 멤버와 눈을 맞추고 끝 박자를 다시 맞춘다.','다음 동작이 잠깐 생각나지 않는다. 어깨로 리듬을 이어가며 마지막 포즈를 기다린다.','발을 바꾸는 순간 동작이 엉킨다. 그래도 멈추지 않고 멤버를 따라 끝까지 간다.','힘껏 움직이다 순서를 하나 건너뛴다. 객석에 웃어 보이고 마지막 박자에 다시 합류한다.']},
 groove:{ready:['어깨로 리듬을 타다가 손동작도 슬쩍 얹어본다. 옆에서 지켜보는 멤버에게 웃어 보인다.','첫 박자를 입으로 작게 세어본다. 이번에는 여유 있게 해보려는 듯 어깨를 한번 푼다.','고개로 박자를 세다가 손끝으로 리듬을 옮긴다. 춤으로 보이려니 조금 멋쩍게 웃는다.','다음 멤버와 눈을 맞추며 박자를 탄다. 자기 차례를 기다리는 동안 발끝은 이미 움직인다.'],success:['작은 동작으로 박자를 끝까지 지킨다. 마지막에 웃으며 손을 흔들자 객석도 함께 흔들린다.','서두르지 않고 포인트 동작을 하나씩 남긴다. 마지막 눈맞춤 뒤에는 쑥스러운 웃음이 온다.','리듬에 맞춰 움직이다 멤버의 환호를 듣고 웃는다. 마지막 동작에도 그 미소가 그대로 남는다.','다음 멤버에게 박자를 건네듯 손을 내민다. 짧은 눈맞춤 끝에 둘 다 웃음을 터뜨린다.'],stumble:['손이 먼저 나갔다가 박자를 한번 놓친다. 어깨로 리듬을 이어가며 웃는 얼굴로 돌아온다.','포인트 동작을 작게 틀리고는 혼자 웃는다. 발끝으로 박자를 다시 잡고 마지막을 맞춘다.','다음 동작 대신 고개만 박자를 탄다. 멤버의 신호를 알아보고 웃으며 포즈를 잇는다.','몸은 신이 났는데 손이 잠깐 길을 잃는다. 웃으며 멤버 쪽으로 다가가 끝 포즈를 같이 잡는다.']}
};
const reactionBeforeVoyage=challengeReaction;challengeReaction=function(who,id,result){const x=CHALLENGES.find(c=>c.id===id);if(!x||who<0||who>3)return '';const phase=!result?'ready':['perfect','close'].includes(result)?'success':'stumble';return storyVariant(S,'challenge/'+who+'/'+id+'/'+phase)?CHALLENGE_OTHER_LINES[challengeMood(x)][phase][who]:reactionBeforeVoyage(who,id,result)};
const echoBeforeVoyage=choiceEcho;choiceEcho=function(){let html=echoBeforeVoyage();if(!S||!storyVariant(S,'echo/'+S.step))return html;const lines={'이 장면, 우리 색깔이 보여서 좋아.':'이 장면은 객석에서도 오래 기억하겠는데?','객석이랑 같이 즐길 수 있겠는데?':'이 구간은 같이 웃으면서 할 수 있겠다.','편곡과 연주 구성이 마음에 들어.':'소리가 쌓이는 순서가 좋아. 합주 때 한번 이어보자.','이렇게 준비하면 무대에서 더 편하게 칠 수 있어.':'점검할 게 정리됐네. 이제 연주에 더 집중할 수 있겠어.','내가 생각했던 장면도 조금 남겨주면 좋겠어.':'좋아. 내가 떠올린 장면도 다음 구간에 조금 넣어볼까?','관객이 같이 들어올 틈이 있으면 좋겠어.':'관객이랑 눈 맞출 시간도 한 군데쯤 남기자.','곡이 바뀔 때 템포와 첫 박자를 합주 때 확인하자.':'다음 노래로 넘어가는 박자는 같이 맞춰보고 싶어.','좋은데, 점검할 시간은 꼭 남겨줘.':'할 수는 있어. 대신 장비와 동선 확인은 같이 해보자.'};for(const [a,b]of Object.entries(lines))html=html.replace(a,b);return html};
function meetingMemo(s,who){const titles=s.set.map(id=>track(id).title),has=t=>titles.includes(t),picked=s.set.map(id=>track(id));let lines;
 if(who===0){if(has('카멜레온'))lines=['카멜레온을 골랐네. 베이스가 앞에 나오는 구간에서는 바이올린 소리를 조금 비워주면 좋겠어. 서로 언제 들어오는지 눈 맞추면서 해보자.','카멜레온에서는 원상이 손끝이 잘 보였으면 좋겠어. 나는 베이스가 들어올 자리에 선율을 겹치지 않게 맞춰볼게.'];else{const hard=picked.find(x=>x.group!=='solo'&&x.diff[0]>=9);lines=hard?[hard.title+'은 활 움직임이 많으니까, 그 구간에서는 동선을 단순하게 잡고 연주하는 손을 가까이 보여주자.',hard.title+'을 할 때는 조명보다 첫 박자가 먼저야. 시작 신호를 정하고 손끝이 보이는 장면을 남겨보자.']:['바이올린 선율이 시작되는 순간에는 무대를 조금 비워두고 싶어. 객석에서도 우리가 서로 보는 눈빛까지 보이면 좋겠어.','곡마다 앞에 나서는 사람이 다르잖아. 그 순간에 시선이 자연스럽게 모이는 무대를 만들자.']}}
 if(who===1){const hard=picked.filter(x=>(x.soloMember===undefined||x.soloMember===1)&&x.diff[1]>=9);if(has('파울'))lines=['파울은 후반에 목소리를 많이 쓰니까, 앞뒤 곡 사이에 물 마실 틈은 남겨두자. 객석을 보는 시간도 조금 있었으면 좋겠어.','파울 마지막까지 힘 있게 부르고 싶어. 그 전에 마이크와 물 위치부터 정해두고, 다음 노래 시작을 조금 여유 있게 맞추자.'];else if(hard.length>=3)lines=[hard.slice(0,2).map(x=>x.title).join('에 ')+'까지 있네. 높은 음이 이어지니까 후반에 숨 돌릴 구간을 하나 남겨두자.','오늘 목소리를 크게 쓰는 곡이 '+hard.length+'곡이야. 멘트를 넣을 자리를 정해두면 마지막까지 더 잘 들려줄 수 있을 것 같아.'];else if(has('Run To You'))lines=['Run To You에서는 마지막 음까지 목소리에 집중하고 싶어. 노래가 끝난 뒤 한 박자만 더 기다렸다가 다음 무대로 가자.','Run To You는 서두르지 않고 부르고 싶어. 시작하기 전에 객석이 조용해질 시간을 조금만 남겨줄래?'];else lines=['목소리를 크게 내는 곡 사이에는 관객이랑 눈 맞출 시간도 남기자. 같이 부를 구간은 손으로 신호를 줄게.','끝까지 노래하려면 쉬는 자리도 정해둬야 해. 짧은 멘트 한 번이 다음 곡의 호흡을 바꿀 수 있거든.']}
 if(who===2){if(s.special==='pass'&&has('카멜레온'))lines=['파사칼리아에서 카멜레온으로 바로 이어가네. 두 악기로 끝내는 마지막 박자와 베이스 첫 소리가 딱 붙도록 합주 때 맞춰보자.','파사칼리아 뒤에 카멜레온이면 베이스를 계속 이어갈 수 있겠어. 드럼이 들어오는 박자는 광일이랑 먼저 정해둘게.'];else if(has('카멜레온'))lines=['카멜레온은 베이스 주법이 빠르게 바뀌니까, 앞 곡 끝에서 손을 정리할 틈이 필요해. 시작 신호를 한번 맞춰보자.','카멜레온 첫 베이스가 또렷하게 들리면 좋겠어. 다른 악기가 합류하는 순간까지 음량을 같이 잡아보자.'];else if(s.picks.arrange==='medley')lines=['곡을 이어 붙였으니 끝나는 박자와 다음 시작을 맞춰보자. 전주가 길어지는 구간은 드럼이 먼저 신호를 주면 좋겠어.','메들리는 멈추지 않는 게 핵심이니까, 악기 바꾸는 사람의 시간을 먼저 재보자. 이어지는 박자는 그다음에 맞출게.'];else lines=['앞 곡의 마지막 음이 끝난 뒤 다음 곡 첫 박자가 어떻게 들릴지 합주해보자. 조용히 넘길 곳과 끊어서 갈 곳을 정하고 싶어.','좋아하는 곡들을 골랐으니 이제 곡 사이를 맞춰보자. 베이스가 먼저 들어갈 구간은 내가 눈으로 신호를 줄게.']}
 if(who===3){const hard=picked.filter(x=>x.group!=='solo'&&x.diff[3]>=9);if(hard.length>=2)lines=[hard.slice(0,2).map(x=>x.title).join('에 ')+'까지 있네. 드럼을 세게 치는 곡이 이어지니 그 전에 물 마실 자리부터 정해두자.','후반에 드럼이 촘촘한 곡이 '+hard.length+'곡 있어. 끝까지 박자를 지킬 수 있게 전환 신호와 쉬는 시간을 같이 맞춰보자.'];else if(s.picks.session&& !['band','basic'].includes(s.picks.session))lines=['추가 연주자가 있으니까 모니터 소리와 입장 신호를 한번 더 확인하자. 드럼 첫 박자는 모두 들을 수 있어야 해.','연주자가 늘었네. 내 시작 신호가 뒤쪽까지 보이는지 확인하고, 모니터 소리는 합주하면서 잡아보자.'];else if(s.special==='blind')lines=['안대 무대가 있으니까 예찬이 자리와 장비 선부터 확인하자. 끝나고 다음 곡으로 넘어갈 신호도 내가 같이 볼게.','안대 쓰고 움직일 구간은 비워두자. 공연 전에 바닥과 케이블을 확인하면 나도 드럼에 더 집중할 수 있어.'];else lines=['첫 박자를 줄 때 서로 눈이 닿는지 확인하자. 마이크와 모니터까지 맞춰놓으면 무대에서는 연주에만 집중할 수 있겠어.','조명 바뀌는 순간에 시작 신호가 가려지지 않았으면 좋겠어. 합주하면서 모니터 소리도 한번 더 확인하자.']}
 return lines[storyVariant(s,'meeting/'+who)]}
const meetingBeforeVoyage=meetingView;meetingView=function(who){return meetingBeforeVoyage(who).replace(/<blockquote>[\s\S]*?<\/blockquote>/,`<blockquote>“${esc(meetingMemo(S,who))}”</blockquote>`)};
function encoreStatus(s,x){const item={kind:'track',id:x.id},cost=Game.cost(s,item),reasons=[];s.sat.forEach((v,i)=>{if(v<75)reasons.push(MEMBERS[i].short+' 만족도 '+Math.ceil(75-v)+' 부족')});if(s.audience<80)reasons.push('관객 만족도 '+Math.ceil(80-s.audience)+' 부족');if(Game.execution(s,item)<65)reasons.push('합주·기술 준비 부족');cost.forEach((v,i)=>{if(v>s.energy[i])reasons.push(MEMBERS[i].short+' 체력 '+(v-s.energy[i])+' 부족')});const time=Game.duration(s,item)-(s.limit-s.elapsed);if(time>0)reasons.push('공연 시간 '+time+'분 부족');return {ready:Game.encoreGate(s)&&Game.encoreReady(s,x),reasons}}
function sortedEncorePool(s){return Game.encorePool(s).map((x,i)=>({x,i,status:encoreStatus(s,x)})).sort((a,b)=>Number(b.status.ready)-Number(a.status.ready)||a.i-b.i).map(o=>o.x)}
const songCardBeforeVoyage=songCard;songCard=function(x,encore=false){let html=songCardBeforeVoyage(x,encore);if(encore){const st=encoreStatus(S,x);html=html.replace(/<div class="cardnote">[\s\S]*?<\/div>/,`<div class="cardnote encore-reason ${st.ready?'encore-available':''}">${st.ready?'지금 연주 가능':st.reasons.map(esc).join(' · ')}</div>`)}return html};
const songInfoBeforeVoyage=songInfo;songInfo=function(id){songInfoBeforeVoyage(id);if(S?.phase==='encore'){const st=encoreStatus(S,track(id));$('#modalbody').innerHTML+=`<section class="encore-detail"><h3>${st.ready?'지금 무대로 돌아갈 수 있어':'이 곡을 더하려면'}</h3>${st.reasons.map(r=>'<p>'+esc(r)+'</p>').join('')}</section>`}};
encoreView=function(){if(Game.fatigueGate(S))return fatigueView();const pool=sortedEncorePool(S),max=Math.max(1,Math.ceil(pool.length/4)),ready=pool.filter(x=>encoreStatus(S,x).ready);S.encorePage=Math.min(S.encorePage||0,max-1);return heading('HOMEWARD / ENCORE '+S.encores,'한 번만 더, 이 섬에 머물까요?','지금 가능한 곡부터, 한 번 더 머무는 시간. 관객의 마음과 네 사람의 남은 체력.')+`<div class="encorechecks"><span class="${S.sat.every(v=>v>=75)?'ok':''}">전원 만족도 75 이상</span><span class="${S.audience>=80?'ok':''}">관객 만족도 80 이상</span><span class="${ready.length?'ok':''}">지금 가능한 곡 ${ready.length}곡</span><span>남은 시간 ${S.limit-S.elapsed}분</span></div><button class="primary wide" onclick="finish()">오늘의 마지막 인사로 마무리 ↗</button>${restView()}<div class="encore-pool-label"><span>연주 가능한 곡부터</span><small>곡마다 필요한 체력·시간·완성도 표시.</small></div><div class="songgrid">${pool.slice(S.encorePage*4,S.encorePage*4+4).map(x=>songCard(x,true)).join('')}</div><div class="pager"><span>후보 ${S.encorePage+1} / ${max}</span><button class="secondary" onclick="nextEncorePage()" ${pool.length<=4?'disabled':''}>다른 네 곡 보기 →</button></div>`};
nextEncorePage=function(){S.encorePage=((S.encorePage||0)+1)%Math.max(1,Math.ceil(sortedEncorePool(S).length/4));render()};
function finalReflection(s){if(!s.performed.length)return '아직 객석에 닿지 못한 노래들이 큐시트에 남아 있다. 다음 공연에는 이 준비를 끝까지 이어가 보자.';const played=s.performed.map(it=>({it,x:Game.itemTrack(it,s)})),first=played[0].x.title,last=played.at(-1).x.title,lines=[];if(s.encores>0)lines.push('마지막인 줄 알았던 인사 뒤에 '+s.encores+'번 더 돌아왔다. 「'+last+'」까지 함께한 오늘은 쉽게 끝나지 않을 기억이 되었다.');if(played.some(o=>o.it.kind==='special'&&o.it.id==='pass')&&played.some(o=>o.x.title==='카멜레온'))lines.push('두 악기로 맞췄던 파사칼리아의 끝이 카멜레온의 첫 박자로 이어졌다. 합주실에서 정한 눈맞춤 하나가 오늘의 장면이 되었다.');const solos=played.filter(o=>o.x.soloMember!==undefined);if(new Set(solos.map(o=>o.x.soloMember)).size===4)lines.push('「'+first+'」로 문을 열고, 네 사람의 무대를 하나씩 남겼다. 마지막 「'+last+'」 뒤에는 각자의 소리가 같은 섬에 머물렀다.');if(s.choirSong&&s.incidentSeen.includes('choir'))lines.push('「'+s.choirSong+'」에서 객석이 건넨 목소리가 아직 남아 있다. 준비한 곡을 함께 불러준 순간, 이 공연은 모두의 기억이 되었다.');lines.push('처음의 「'+first+'」부터 마지막 「'+last+'」까지. 큐시트에 적었던 이름들이 이제 오늘의 기억으로 남았다.');return lines[storyVariant(s,'farewell',lines.length)]}
const farewellBeforeVoyage=farewellView;farewellView=function(){return farewellBeforeVoyage().replace('<div class="farewellline"></div>',`<div class="reflection-card"><span class="eyebrow">THE NIGHT WE MADE</span><p>${esc(finalReflection(S))}</p></div><div class="farewellline"></div>`)};
const resultBeforeVoyage=result;result=function(){return `<div class="record-return">${historyReadOnly?'<button class="textbtn" onclick="openPlayHistory()">← 지난 공연 목록</button><button class="textbtn" onclick="resumeVoyage()">저장한 공연으로 돌아가기 ↗</button>':''}</div>`+resultBeforeVoyage().replace('<section class="ticket-keepsake">',`<section class="reflection-card result-reflection"><span class="eyebrow">THE NIGHT WE MADE</span><p>${esc(finalReflection(S))}</p></section><section class="ticket-keepsake">`)};
// Save/history guidance is included in the single guide in app.js.
if(typeof window!=='undefined')window.addEventListener?.('pagehide',()=>persistVoyage());
render();
